from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect width="720" height="260" fill="#f7fbff"/><g font-size="16" font-family="sans-serif">'
for i,(h,x) in enumerate([('Th',200),('H',300),('T',400),('O',500)]): b+=f'<text x="{x}" y="35" font-weight="bold">{h}</text>'
