b+='<line x1="190" y1="205" x2="560" y2="205" stroke="#333" stroke-width="2"/><text x="60" y="245" fill="#2a6">9 + 4 + 5 ones, tens and thousands regroup: 6049 + 3054 = 9103</text></g>'
svgfile('c4-maths-etl-addition.svg',720,260,b)
b='<rect width="720" height="200" fill="#fff8f0"/><g font-size="16" font-family="sans-serif"><rect x="60" y="40" width="560" height="40" fill="#f4a261"/><text x="300" y="66">Assam: 5719</text><rect x="60" y="110" width="400" height="40" fill="#2a9d8f"/><text x="150" y="136" fill="#fff">Meghalaya: ?</text><rect x="460" y="110" width="160" height="40" fill="#e9c46a"/><text x="470" y="136">3965 more</text><text x="60" y="185">Meghalaya = 5719 − 3965 = 1754</text></g>'
svgfile('c4-maths-etl-barmodel.svg',720,200,b)
chapter(4,'maths','elephants-tigers-and-leopards','Elephants, Tigers, and Leopards',
 ('Counting our wild animals','India is rich in biodiversity, and it is home to elephants, tigers and leopards. About three-fourths of the world’s tigers and about three-fifths of the Asiatic elephants live in India. In this chapter you will add and subtract big numbers to count these animals, and you will learn clever shortcuts to solve sums quickly.'),
 [('The NIM game',['Let us play the NIM game for two players, where each player adds either 1 or 2 to the running total.','The player who reaches 10 first is the winner.','If the other player has reached 8 and it is your turn, add 2 and you reach 10, so you win.','If the other player has reached 7 and it is your turn, you lose, because adding 1 gives 8 and adding 2 gives 9, and the other player reaches 10.','If the other player has reached 6, you add 1 to make 7, and then you can always win.','So 7, 4 and 1 are the safe numbers: if you reach one of them, you can always win the game.']),
  ('The addition chart',['The addition chart has numbers 0 to 12 on the top and on the side, and each cell is the row number plus the column number.','The numbers in a row go up by 1 as we move right, and the numbers in a column go up by 1 as we move down.','The number 9 appears 10 times in the chart, and a number like 12 appears many times because many pairs add up to it.','No row or column has only even numbers or only odd numbers, because even and odd numbers alternate.','In a 2 by 2 window, the two diagonal sums are always equal, which is a lovely pattern.']),
  ('Reverse and add',['Take 27 and reverse it to get 72, and 27 + 72 = 99.','Adding a 2-digit number and its reverse always gives a multiple of 11, because the tens and ones digits are both added.','Numbers that give 55 when added to their reverse are 14, 23, 32 and 41, and numbers that give 88 are 17, 26, 35, 44, 53, 62 and 71.','The smallest 3-digit sum is 110, for example 19 + 91 = 110.']),
  ('Adding big numbers: elephants',['The elephants in Karnataka number 6049 and in Kerala 3054, so we add 6049 + 3054.','First estimate: 6000 + 3000 is about 9000.','Ones: 9 + 4 = 13, so write 3 and regroup 1 ten.','Tens: 4 + 5 + 1 = 10, so write 0 and regroup 1 hundred.','Hundreds: 0 + 0 + 1 = 1.','Thousands: 6 + 3 = 9, so there are 9103 elephants in the two states, which is close to our estimate.','Remember that 10 ones make 1 ten, 10 tens make 1 hundred and 10 hundreds make 1 thousand.']),
  ('Adding three numbers: leopards',['Gujarat has 1355 leopards, Karnataka has 1131 and Madhya Pradesh has 1817.','The estimate is 1000 + 1000 + 2000, about 4000.','Ones: 5 + 1 + 7 = 13, write 3 and carry 1 ten.','Tens: 5 + 3 + 1 + 1 = 10, write 0 and carry 1 hundred.','Hundreds: 3 + 1 + 8 + 1 = 13, write 3 and carry 1 thousand.','Thousands: 1 + 1 + 1 + 1 = 4, so there are 4303 leopards in the three states.']),
  ('Tigers and comparing amounts',['Maharashtra has 444 tigers, and Madhya Pradesh has 341 more, so 444 + 341 = 785 tigers.','Uttarakhand has 116 more than Maharashtra, so 444 + 116 = 560 tigers.','Madhya Pradesh and Uttarakhand together have 785 + 560 = 1345 tigers.','All three states have 444 + 1345 = 1789 tigers.','When a problem says more than, we add, and when it says less than, we subtract.']),
  ('Subtracting big numbers',['Assam has 5719 elephants, which is 3965 more than Meghalaya, so Meghalaya has 5719 − 3965.','The estimate is 5700 − 4000, about 1700.','Ones: 9 − 5 = 4.','Tens: 1 is less than 6, so regroup 1 hundred as 10 tens, which makes 11 tens, and 11 − 6 = 5.','Hundreds: 6 is left and 9 is more than 6, so regroup 1 thousand as 10 hundreds, which makes 16 hundreds, and 16 − 9 = 7.','Thousands: 4 is left and 4 − 3 = 1, so Meghalaya has 1754 elephants.','To find an earlier number after an increase, subtract: leopards in 2018 were 8820 − 749 = 8071.']),
  ('Easy ways to add and subtract',['To add 99, add 100 and then subtract 1, so 4596 + 104 is 4600 + 100 = 4700.','To subtract 99, subtract 100 and then add 1, so 8787 − 99 = 8688.','When two numbers are close to round numbers, we can use the round number and then adjust.','To compare 54 + 97 and 54 + 90, notice that the same 54 is added, so the bigger number added gives the bigger total.','Without calculating, 84 − 68 is more than 90 − 68? No, the same 68 is taken away from a smaller 84, so 84 − 68 is less than 90 − 68.','Always estimate first, then check whether your answer is close.'])],
 [('Karnataka has 6049 elephants and Kerala has 3054. How many in all?',[('We add, so 6049 + 3054.','The word in all tells us to add.'),('Ones: 9 + 4 = 13, write 3 and carry 1 ten.','10 ones make a ten.'),('Tens: 4 + 5 + 1 = 10, write 0 and carry 1 hundred. Hundreds: 0 + 0 + 1 = 1.','Keep carrying.'),('Thousands: 6 + 3 = 9, so the answer is 9103.','Add the thousands.')]),
  ('Assam has 5719 elephants, which is 3965 more than Meghalaya. How many does Meghalaya have?',[('Meghalaya has fewer, so we subtract 5719 − 3965.','More than means the other number is smaller.'),('Ones 9 − 5 = 4. Tens: regroup, 11 − 6 = 5.','We borrow 1 hundred.'),('Hundreds: regroup, 16 − 9 = 7. Thousands: 4 − 3 = 1.','Borrow 1 thousand.'),('Meghalaya has 1754 elephants.','Check: 1754 + 3965 = 5719.')]),
  ('In Kaziranga, 6415 visitors came in November, which is 1587 more than October. How many came in October?',[('We subtract, so 6415 − 1587.','October is less than November.'),('Ones: 15 − 7 = 8. Tens: 0 − 8 needs regrouping, 10 − 8 = 2.','Borrow from the hundreds and the tens.'),('Hundreds: 3 − 5 needs regrouping, 13 − 5 = 8. Thousands: 5 − 1 = 4.','Keep regrouping.'),('October had 4828 visitors.','Check: 4828 + 1587 = 6415.')]),
  ('Find 4596 + 104 using an easy way.',[('Notice that 4596 is close to 4600, because 4596 + 4 = 4600.','Look for a round number.'),('Take 4 from 104 to give to 4596, so 4600 + 100.','Move 4 across.'),('4600 + 100 = 4700.','Add the round numbers.')])],
 ('Explain how you add and subtract 4-digit numbers, and how estimating and easy ways help.',['Write numbers in columns with ones under ones','Start from the ones and regroup when 10 or more','Subtract from the ones and borrow when the top digit is smaller','Estimate first to check the answer','Use round numbers to make quick adjustments'],['Forgetting to add the carried digit','Subtracting the smaller digit from the larger','Not checking if the answer is close to the estimate']),
 ['We add big numbers column by column from the ones, carrying when a column makes 10 or more.','We subtract column by column, borrowing from the next place when needed.','More than means add and less than means subtract.','Estimating first helps us check our answer.','Easy ways: add or subtract 100 and adjust, or use round numbers.','Adding a number to its reverse gives a multiple of 11.'],
 [M('1',1,'What is 6049 + 3054?','9103',[('9003','You forgot the carry from the tens'),('3095','That reverses some digits')],'Add column by column with carries to get 9103.'),
  M('2',1,'In NIM with target 10, which total is safe to reach?','7',[('8','From 8 the opponent adds 2 and reaches 10'),('9','From 9 the opponent adds 1 and reaches 10')],'From 7 you can always reach 10 next.'),
  M('3',1,'What is 5719 − 3965?','1754',[('2754','You forgot to borrow once'),('1846','That is from adding instead')],'5719 − 3965 = 1754.'),
  M('4',1,'Which sign completes 54 + 97 ☐ 54 + 90?','>',[('<','97 is more than 90'),('=','The numbers added are different')],'97 is greater than 90, so the first sum is bigger.'),
  M('5',2,'What is the estimate for 6049 + 3054?','About 9000',[('About 3000','That is the difference'),('About 90000','That is far too big')],'6000 + 3000 = 9000.'),
  M('6',2,'Madhya Pradesh has 341 more tigers than Maharashtra (444). How many?','785',[('103','That is 444 − 341'),('685','You added 241 instead of 341')],'444 + 341 = 785.'),
  M('7',2,'What is 8787 − 99 done an easy way?','8688',[('8886','You added 99 instead of subtracting'),('8678','You subtracted 109')],'Subtract 100 to get 8687, then add 1 to get 8688.'),
  M('8',2,'Which number gives 55 when added to its reverse?','23',[('27','27 + 72 = 99'),('46','46 + 64 = 110')],'23 + 32 = 55.'),
  N('9',2,'How many leopards are in 1355 + 1131 + 1817?',4303,'Add the three numbers column by column.',[(4203,'You missed a carry from the hundreds')]),
  N('10',3,'Leopards in 2022 were 8820, which is 749 more than in 2018. How many in 2018?',8071,'8820 − 749 = 8071.',[(9569,'You added instead of subtracting')]),
  F('11',2,'More than means we should subtract to find the larger number.',False,'To find the larger number we add; to find the smaller one we subtract.'),
  F('12',3,'The sum of a 2-digit number and its reverse is always a multiple of 11.',True,'Both tens and ones are added, giving 11 × (sum of the digits).')],
 svgs=[('c4-maths-etl-addition','Column addition of 6049 and 3054 with carries.','6049 + 3054 = 9103.'),('c4-maths-etl-barmodel','A bar model comparing Assam and Meghalaya elephants.','Meghalaya = 5719 − 3965 = 1754.')],
 keep=['regroup','estimate'])
